def numeros_primos(limite):
    primos = []
    for numero in range(2, limite + 1):
        eh_primo = True
        for divisor in range(2, int(numero ** 0.5) + 1):
            if numero % divisor == 0:
                eh_primo = False
                break
        if eh_primo:
            primos.append(numero)
    return primos

